import{n as e}from"./rolldown-runtime-Cyuzqnbw.js";import{A as t}from"./framer-Be3hPn0e.js";import{Jn as n,nr as r,t as i}from"./icons-BIn1f5H-.js";import{n as a,t as o}from"./ArticleLayout-DqTW3R6l.js";var s,c,l=e((()=>{i(),s=[{"@context":`https://schema.org`,"@type":`Article`,headline:`Assurance auto pour un voyage à l'étranger : ce qu'il faut vérifier avant de partir`,description:`Partir en voiture à l'étranger ? Pays couverts sans formalité, pays où la carte internationale d'assurance reste exigée : ce qu'il faut vérifier avant le départ.`,author:{"@type":`Organization`,name:`Evidence Assurances`},publisher:{"@type":`Organization`,name:`AssuTempo`,logo:{"@type":`ImageObject`,url:`https://assutempo.fr/logo.png`}},mainEntityOfPage:`https://assutempo.fr/articles/assurance-auto-voyage-etranger`,datePublished:`2026-09-08`,dateModified:`2026-09-08`},{"@context":`https://schema.org`,"@type":`BreadcrumbList`,itemListElement:[{"@type":`ListItem`,position:1,name:`Accueil`,item:`https://assutempo.fr`},{"@type":`ListItem`,position:2,name:`Articles`,item:`https://assutempo.fr/articles`},{"@type":`ListItem`,position:3,name:`Assurance auto pour un voyage à l'étranger`,item:`https://assutempo.fr/articles/assurance-auto-voyage-etranger`}]},{"@context":`https://schema.org`,"@type":`FAQPage`,mainEntity:[{"@type":`Question`,name:`Faut-il encore une carte verte pour partir en vacances en voiture à l'étranger ?`,acceptedAnswer:{"@type":`Answer`,text:`Le document papier vert a disparu en France le 1er avril 2024, remplacé par le Fichier des Véhicules Assurés (FVA) sur le territoire national. À l'étranger, le principe international qu'il portait subsiste sous le nom de carte internationale d'assurance automobile (IMIC), imprimée sur fond blanc, exigée dans une poignée de pays précis.`}},{"@type":`Question`,name:`Dans quels pays la plaque d'immatriculation française suffit-elle à circuler assuré ?`,acceptedAnswer:{"@type":`Answer`,text:`Dans l'ensemble de l'Union européenne et de l'Espace économique européen, ainsi que dans quelques pays voisins comme le Royaume-Uni, la Suisse, l'Andorre, la Serbie, la Bosnie-Herzégovine ou le Monténégro, la seule plaque d'immatriculation française vaut présomption d'assurance, sans document à présenter.`}},{"@type":`Question`,name:`Quels pays exigent encore la carte internationale d'assurance (IMIC) ?`,acceptedAnswer:{"@type":`Answer`,text:`L'Albanie, l'Azerbaïdjan, la Macédoine du Nord, le Maroc, la Moldavie, la Tunisie et la Turquie demandent la présentation de cette carte aux postes-frontières pour un véhicule immatriculé en France.`}},{"@type":`Question`,name:`Comment obtenir la carte internationale d'assurance automobile pour l'un de ces pays ?`,acceptedAnswer:{"@type":`Answer`,text:`En dehors du contrat standard, ces destinations nécessitent un devis établi sur mesure par l'assureur en fonction du véhicule, du conducteur et de la durée du séjour. Mieux vaut anticiper la demande plusieurs jours avant le départ plutôt que la veille.`}},{"@type":`Question`,name:`Que faire si le pays de destination ne fait partie ni de l'Union européenne ni de la liste des pays à carte internationale ?`,acceptedAnswer:{"@type":`Answer`,text:`Le véhicule sort alors du système multilatéral de la carte verte. Une assurance locale, dite assurance frontière, doit en général être souscrite à l'entrée du pays. Les conseils aux voyageurs du ministère des Affaires étrangères (diplomatie.gouv.fr) détaillent les démarches propres à chaque destination.`}}]}],c={slug:`assurance-auto-voyage-etranger`,seo:{title:`Assurance auto voyage à l'étranger : le guide`,description:`Partir en voiture à l'étranger ? Pays couverts sans formalité, pays où la carte internationale d'assurance reste exigée avant de rouler.`,canonical:`https://assutempo.fr/articles/assurance-auto-voyage-etranger`,jsonLd:s},category:`International`,readTime:`7 min`,updatedDate:`8 septembre 2026`,author:`Evidence Assurances`,headline:`Assurance auto pour un voyage à l'étranger : ce qu'il faut vérifier avant de partir`,cta:{href:`/assurance-internationale`,label:`Demander mon devis international`,title:`Devis sur mesure pour circuler hors du contrat standard.`,subtitle:`Carte internationale d'assurance établie pour la durée exacte du séjour.`,suffix:`Réponse sous 4h en journée, 8h la nuit.`},answerCapsule:{answer:`Dans la quasi-totalité de l'Europe, la plaque d'immatriculation française suffit à prouver l'assurance, sans document à présenter. Sept pays font exception (Maroc, Tunisie, Turquie, Albanie, Azerbaïdjan, Moldavie, Macédoine du Nord) : ils exigent la carte internationale d'assurance automobile, l'héritière de l'ancienne carte verte, à demander à l'assureur avant le départ.`,facts:[{anchor:`1er avril 2024`,text:`Date de suppression du document papier vert en France, remplacé par le Fichier des Véhicules Assurés (FVA) sur le territoire national.`},{anchor:`35 pays`,text:`Nombre de pays européens et voisins où la seule plaque d'immatriculation vaut présomption d'assurance, sans carte à présenter (europa.eu).`},{anchor:`7 pays à carte obligatoire`,text:`Maroc, Tunisie, Turquie, Albanie, Azerbaïdjan, Moldavie et Macédoine du Nord exigent encore la carte internationale d'assurance automobile.`},{anchor:`8h la nuit`,text:`Délai de réponse au devis sur mesure AssuTempo pour ces sept destinations, y compris la nuit et le dimanche.`}],updated:`8 septembre 2026`},sections:[{type:`alert`,heading:`L'essentiel`,items:[`La carte verte papier a disparu en France le 1er avril 2024, remplacée par le Fichier des Véhicules Assurés (FVA) sur le territoire national.`,`À l'étranger, le principe qu'elle portait continue d'exister sous le nom de carte internationale d'assurance automobile (IMIC), imprimée sur fond blanc.`,`Dans la plupart des pays européens, la plaque d'immatriculation suffit désormais, sans carte à présenter.`,`Sept pays font exception et exigent encore cette carte : Maroc, Tunisie, Turquie, Albanie, Azerbaïdjan, Moldavie et Macédoine du Nord.`]},{type:`text`,heading:`Faut-il encore une carte verte pour rouler à l'étranger ?`,paragraphs:[`La question revient à chaque départ en vacances, et la réponse a changé récemment. Le document papier vert, familier depuis des décennies, a disparu en France le 1er avril 2024. Sur le territoire national, la preuve d'assurance repose désormais sur le Fichier des Véhicules Assurés (FVA), consulté directement à la plaque d'immatriculation par les forces de l'ordre.`,`Ce que la disparition du papier vert change moins, c'est le principe international qu'il portait. L'accord multilatéral entre assureurs européens, géré par le Conseil des Bureaux, continue de couvrir un véhicule qui circule d'un pays à l'autre. Ce filet s'appelle désormais carte internationale d'assurance automobile, parfois abrégée IMIC, et n'est plus imprimé en vert mais sur fond blanc.`],relatedLink:{text:`Mémo Véhicule Assuré, FVA, carte internationale : le détail des documents`,href:`/articles/assurance-temporaire-attestation-immediate`}},{type:`table`,heading:`Quel document selon la destination ?`,intro:`Trois situations bien distinctes, à vérifier avant de prendre la route plutôt qu'au poste-frontière.`,columns:[`Destination`,`Document à avoir`,`Démarche avant le départ`],rows:[[`Union européenne, Espace économique européen, Royaume-Uni, Suisse et quelques voisins proches`,`Aucun, la plaque d'immatriculation suffit`,`Aucune démarche particulière, garder son attestation d'assurance habituelle en cas de doute`],[`Maroc, Tunisie, Turquie, Albanie, Azerbaïdjan, Moldavie, Macédoine du Nord`,`Carte internationale d'assurance automobile (IMIC)`,`Demander la carte à l'assureur plusieurs jours avant le départ, garder une version imprimée`],[`Pays hors du système de la carte verte (hors Europe et hors des 7 pays ci-dessus)`,`Assurance locale dite assurance frontière`,`Se renseigner sur place ou via les conseils aux voyageurs (diplomatie.gouv.fr) avant l'entrée dans le pays`]],note:`Cette répartition évolue peu mais reste à vérifier avant chaque départ, notamment pour les pays limitrophes de l'Union européenne dont le statut peut changer.`},{type:`text`,heading:`Dans quels pays la plaque française suffit-elle vraiment ?`,paragraphs:[`L'ensemble des États membres de l'Union européenne et de l'Espace économique européen accepte la seule plaque d'immatriculation comme preuve d'assurance. S'y ajoutent des pays voisins signataires du même accord multilatéral : le Royaume-Uni, la Suisse, l'Andorre, la Serbie, la Bosnie-Herzégovine, le Monténégro, Monaco, Gibraltar, Saint-Marin et la Cité du Vatican. Au total, une trentaine de destinations européennes ne demandent plus aucun document particulier (europa.eu).`,`Pour un road trip classique en Espagne, en Italie ou en Allemagne, la question ne se pose donc plus. Le contrat français reste valable, la garantie responsabilité civile s'applique automatiquement, et aucun papier n'est à sortir sauf demande explicite d'un agent local.`],relatedLink:{text:`Les 34 pays couverts par le contrat AssuTempo standard`,href:`/carte`}},{type:`text`,heading:`Et pour les pays qui exigent encore la carte internationale d'assurance ?`,paragraphs:[`Sept destinations sortent de ce cadre simplifié : le Maroc, la Tunisie, la Turquie, l'Albanie, l'Azerbaïdjan, la Moldavie et la Macédoine du Nord. Un véhicule immatriculé en France qui y circule doit présenter la carte internationale d'assurance automobile aux autorités locales, faute de quoi il s'expose à devoir souscrire une couverture sur place, dans l'urgence et à un tarif rarement avantageux.`,`Un conseiller AssuTempo a suivi le cas d'une famille partie au Maroc en camping-car, qui pensait que son contrat annuel suffisait comme pour un trajet en Espagne l'été précédent. La différence tient justement à ce statut particulier : ces sept pays ne sont pas couverts par la simple présomption liée à la plaque, même si l'assureur français reste, sur le fond, celui qui porte le risque.`]},{type:`decisionsplit`,question:`Contrat standard ou devis sur mesure : lequel demander ?`,ariaLabel:`Comparaison entre le contrat standard couvrant l'Europe et le devis sur mesure pour les 7 pays exigeant la carte internationale d'assurance`,voies:[{statut:`ok`,icon:n,titre:`Voyage dans un pays européen classique`,verdict:`Le contrat d'assurance habituel suffit. La plaque d'immatriculation vaut présomption d'assurance dans l'ensemble de l'Union européenne et des pays voisins signataires de l'accord multilatéral.`},{statut:`vigilance`,icon:r,titre:`Voyage au Maroc, en Tunisie, en Turquie ou dans l'un des 4 autres pays`,verdict:`Un devis sur mesure est nécessaire pour obtenir la carte internationale d'assurance. À demander plusieurs jours avant le départ, jamais la veille, pour laisser le temps à l'assureur d'établir le document.`}]},{type:`checklist`,heading:`Avant de prendre la route pour l'un de ces sept pays`,intro:`Quelques réflexes suffisent à éviter une mauvaise surprise au poste-frontière.`,items:[`Vérifier la date d'expiration du contrat d'assurance actuel par rapport aux dates réelles du séjour`,`Demander le devis dédié plusieurs jours avant le départ, l'établissement du document n'étant pas instantané`,`Imprimer la carte internationale d'assurance automobile, certains postes-frontières n'acceptant pas toujours le format numérique`,`Vérifier également la validité du permis de conduire et de la carte grise pour la durée du séjour`,`Consulter les conseils aux voyageurs du pays concerné sur diplomatie.gouv.fr avant le départ`]},{type:`text`,heading:`Et si le pays visité ne fait partie d'aucun de ces deux systèmes ?`,paragraphs:[`Certaines destinations, hors d'Europe et hors des sept pays cités plus haut, ne participent pas du tout à l'accord multilatéral de la carte verte. Le contrat français n'y a alors aucune portée automatique. La solution la plus courante consiste à souscrire une assurance locale, appelée assurance frontière, directement à l'entrée du territoire, souvent pour une durée limitée renouvelable.`,`Les modalités varient fortement d'un pays à l'autre et changent parfois d'une année sur l'autre. Les conseils aux voyageurs publiés par le ministère de l'Europe et des Affaires étrangères (diplomatie.gouv.fr) restent la source la plus fiable à consulter avant un tel départ, plutôt qu'un forum ou un témoignage isolé.`],relatedLink:{text:`Le cas inverse : assurer en France un véhicule immatriculé à l'étranger`,href:`/articles/assurance-temporaire-vehicule-etranger-france`}},{type:`text`,heading:`Le devis peut-il se préparer un dimanche ou un soir avant un départ matinal ?`,paragraphs:[`Un départ en vacances se cale rarement sur les horaires d'un service client classique. AssuTempo reste, à notre connaissance, le seul courtier à maintenir un Guichet de Nuit de 21h à 9h en semaine et sans interruption le dimanche, y compris pour préparer un devis sur mesure vers l'un des sept pays à carte internationale obligatoire : la réponse arrive alors sous 8 heures au lieu de 4 en journée, mais reste possible en dehors des horaires classiques.`],relatedLink:{text:`Le Guichet de Nuit, souscrire hors des horaires classiques`,href:`/articles/assurance-auto-temporaire-nuit-dimanche`}},{type:`text`,heading:`Ce qu'il faut retenir avant de partir`,paragraphs:[`Un départ en voiture à l'étranger ne demande, dans l'immense majorité des cas européens, aucune démarche particulière : la plaque d'immatriculation suffit. La vigilance se concentre sur une liste courte et précise, sept pays où la carte internationale d'assurance automobile reste exigée, et sur les destinations hors du système multilatéral, où une assurance locale prend le relais. Le bon réflexe reste le même partout : vérifier le statut du pays avant de partir, pas au poste-frontière.`],relatedLink:{text:`Demander un devis pour un pays à carte internationale obligatoire`,href:`/assurance-internationale`}}],faqItems:[{q:`Faut-il encore une carte verte pour partir en vacances en voiture à l'étranger ?`,a:`Le papier vert a disparu en France le 1er avril 2024, remplacé par le FVA sur le territoire national. À l'étranger, le principe subsiste sous le nom de carte internationale d'assurance automobile, sur fond blanc, exigée dans une poignée de pays précis.`},{q:`Dans quels pays la plaque d'immatriculation française suffit-elle ?`,a:`Dans l'Union européenne, l'Espace économique européen et quelques pays voisins (Royaume-Uni, Suisse, Andorre, Serbie, Bosnie-Herzégovine, Monténégro...), la plaque vaut présomption d'assurance, sans document à présenter.`},{q:`Quels pays exigent encore la carte internationale d'assurance (IMIC) ?`,a:`Le Maroc, la Tunisie, la Turquie, l'Albanie, l'Azerbaïdjan, la Moldavie et la Macédoine du Nord demandent la présentation de cette carte aux postes-frontières.`},{q:`Comment obtenir la carte internationale d'assurance pour l'un de ces pays ?`,a:`Ces destinations nécessitent un devis établi sur mesure selon le véhicule, le conducteur et la durée du séjour. Mieux vaut anticiper la demande plusieurs jours avant le départ.`},{q:`Que faire si le pays de destination ne fait partie d'aucun des deux systèmes ?`,a:`Une assurance locale, dite assurance frontière, doit en général être souscrite à l'entrée du pays. Les conseils aux voyageurs de diplomatie.gouv.fr détaillent les démarches propres à chaque destination.`},{q:`Combien de temps à l'avance faut-il demander un devis pour ces sept pays ?`,a:`Plusieurs jours avant le départ dans l'idéal, le document n'étant pas délivré instantanément. Un devis reste possible la nuit ou le dimanche via le Guichet de Nuit, avec une réponse sous 8 heures.`}]}}));function u(){return(0,d.jsx)(o,{data:c})}var d;e((()=>{a(),l(),d=t()}))();export{u as default};